Item.method_code:
const { item } = options;
if (!item) {
	return false;
}

const { globalCommand } = commands;
if (!globalCommand.canExecute()) {
	return false;
}

const lockedById = item['locked_by_id'];
const isLockedByOther = lockedById && lockedById !== aras.user.id;
if (isLockedByOther) {
	const message = aras.getResource(
		'',
		'itemsgrid.unable_complete_task_claimed_by_someone_else'
	);
	commands.setErrorMessage(message);
	return false;
}

return true;
